#!/usr/bin/env python3
"""Ливрея Williams (v1.17.43): фигуры в метрах болида -> tools/livery/williams.json (пиксели «фото» по калибровке вида).
   python3 -I tools/livery/williams_gen.py tools/livery/williams.json; затем livery.py -> wrap.js -> livery.py (как у всех команд).
   v1.17.43 (второй заход): фото сбоку (williams/side.jpg, отражено) — высоты зон по нему; первый заход был без него, по ортоснимку модели
   (williams/side_model.png) и 3/4. Плечо понтона у W17 ниже (справка лучом: 0.63 -> 0.37 м к корме) — зоны по высотам фото."""
import json,sys
OUT=sys.argv[1]
SP,SCX,SCY=201.2,321,442     # сбоку: фото команды, нос вправо — отражено; калибровка по ступицам (база 684 пикс = 3.40 м)
TP,TCX,TCY=200.3,302,349     # сверху: фото команды, калибровка по ступицам (база 681 пикс = 3.40 м), силуэт W17 лёг без поправок
sd=lambda z,y:[round(SCX+(1.80-z)*SP,1),round(SCY-(y-0.355)*SP,1)]
tp=lambda z,x:[round(TCX+(1.80-z)*TP,1),round(TCY-x*TP,1)]
P=lambda f,pts:[f(*q) for q in pts]
top=[];side=[]
# ---- сбоку (база — тёмно-синяя: верх носа и шасси, капот, плавник). Высоты — по фото сбоку (у W17 плечо понтона ниже — к корме голубое и белое
# ложатся и на бок капота); B — низ понтона W17 (справка лучом поперёк: ниже краски нет), W — верх белого, T — верх голубого
B=[(0.85,0.46),(0.52,0.46),(0.30,0.458),(0.15,0.455),(0.05,0.415),(-0.50,0.405),(-0.80,0.40),(-1.00,0.36),(-1.10,0.36)]
W=[(0.30,0.462),(0.20,0.47),(0.036,0.509),(-0.10,0.545),(-0.317,0.584),(-0.70,0.600),(-1.018,0.608),(-1.10,0.585)]
T=[(0.85,0.683),(0.40,0.675),(-0.05,0.668),(-0.55,0.655),(-1.02,0.638),(-1.12,0.62)]
side.append({"c":"ink","note":"чёрный борт носа и шасси до понтона (место Stephens, KEEPER; синяя — только полоса по верху: на носу 2.5 см под верхом W17, на шасси от 0.625 м), под понтоном карбон, за понтоном — низ капота над задним колесом (место Gulf)",
  "p":P(sd,[(3.4,-0.1),(3.4,0.25),(3.1,0.26),(3.0,0.27),(2.8,0.365),(2.6,0.435),(2.4,0.49),(2.2,0.54),(2.0,0.58),(1.8,0.61),(1.6,0.625),(0.85,0.625)]+B+[(-1.12,0.52),(-1.30,0.585),(-1.76,0.62),(-1.76,-0.1)])})
side.append({"c":"ink","note":"чёрный верх за гало и воздухозаборник (место DURACELL): нижний край — косой, от подголовника к капоту за воздухозаборником",
  "p":P(sd,[(0.45,0.80),(0.45,1.3),(-0.62,1.3),(-0.62,1.065),(-0.58,1.06)])})
side.append({"c":"lblue","wrap":True,"note":"голубой верх понтона от входа (место Barclays): у входа во всю высоту, к корме — полоса 3 см над белым",
  "p":P(sd,[B[0]]+T+W[::-1]+[(0.30,0.458),(0.52,0.46)])})
side.append({"c":"white","wrap":True,"note":"белый низ понтона (место KOMATSU): острый передний край, к корме поднимается до 0.61 м",
  "p":P(sd,W+[(-1.14,0.51),(-1.12,0.37)]+[q for q in B[::-1] if q[0]<=0.30])})
side.append({"c":"purple","note":"щиток заднего крыла: верх — сине-фиолетовая панель во всю длину (место KOMATSU)","p":P(sd,[(-1.70,1.3),(-1.70,0.79),(-2.5,0.79),(-2.5,1.3)])})
side.append({"c":"white","note":"щиток заднего крыла: белая панель под ней","p":P(sd,[(-1.70,0.79),(-2.5,0.79),(-2.5,0.47),(-1.70,0.47)])})
side.append({"c":"ink","note":"щиток заднего крыла: низ чёрный (место FW)","p":P(sd,[(-1.70,0.47),(-2.5,0.47),(-2.5,-0.1),(-1.76,-0.1)])})
# ---- сверху
top.append({"c":"ink","note":"переднее крыло: середина под носом, щитки и всё снаружи закрылков — карбон (на фото чёрные с ATLASSIAN); нос — синий до |x| 0.15","p":P(tp,[(3.4,0.15),(3.4,1.0),(2.15,1.0),(2.15,0.15)])})
top.append({"c":"white","note":"кончики закрылков переднего крыла — белые (на фото белая передняя часть крыла с kraken; у W17 краска — только кончики закрылков)","p":P(tp,[(3.4,0.45),(3.4,0.62),(2.15,0.62),(2.15,0.45)])})
top.append({"c":"ink","note":"чёрный верх воздухозаборника за дугой (место DURACELL), скруглён к корме",
  "p":P(tp,[(0.08,0.0),(0.08,0.17),(-0.10,0.20),(-0.30,0.18),(-0.45,0.13),(-0.52,0.06),(-0.53,0.0)])})
top.append({"c":"ink","note":"заднее крыло: основная плоскость сверху — карбон (ATLASSIAN на чёрном)","p":P(tp,[(-1.76,0.0),(-1.76,1.0),(-2.10,1.0),(-2.10,0.0)])})
top.append({"c":"lblue","note":"заднее крыло: верхний закрылок голубой (на фото сзади — BARCLAYS на голубом; сверху его передняя часть чёрная — проекция не различает, как синий закрылок Ferrari)","p":P(tp,[(-2.10,0.0),(-2.10,1.0),(-2.5,1.0),(-2.5,0.0)])})
cfg={"key":"williams","team":"Williams","color":"#7EC8FF","halo":"#121620",
 "src":"FW48 2026 по 6 фото владельца 05.11.2026 (сверху, сзади, 3/4 спереди, 3/4 сзади, спереди, кокпит) и фото сбоку (отражено), стилизация; надписи и логотипы не переносятся",
 "palette":{"blue":["#0a2470",0.15],"ink":["#16171a",0.15],"lblue":["#3a8ec8",0.1],"white":["#b4b8c0",0.3],"purple":["#140c5a",0.2]},
 "num":{"w":0.09,"o":0,"nose":"#e8eaee","side":"#e8eaee","hn":0.15,"hs":0.11,"note":"белые цифры заливкой, прямые («23» на носу, как на фото)"},
 "base":"blue","layers":["ink","lblue","white","purple"],
 "top":{"photo":"williams/top.jpg","ppm":TP,"cx":TCX,"cy":TCY,"note":"фото команды сверху, нос влево; калибровка по ступицам (база 681 пикс = 3.40 м), силуэт W17 ортокамерой лёг без поправок","shapes":top},
 "side":{"photo":"williams/side.jpg","ppm":SP,"cx":SCX,"cy":SCY,"note":"фото команды сбоку (дано владельцем вторым заходом), нос вправо — отражено; калибровка по ступицам (база 684 пикс = 3.40 м), силуэт W17 ортокамерой лёг без поправок (шины на фото на ~6 % меньше модели, нос FW48 чуть ниже)","shapes":side}}
s=json.dumps(cfg,ensure_ascii=False).replace('{"c"','\n   {"c"')
open(OUT,'w').write(s);print(len(top),len(side))
